/**
 * SAM-hosted git for the self-host build only: the `HostedGitRepo` Durable Object class (vendored
 * dgit core and pako) and the git smart-HTTP route.
 *
 * Only the celld entry generated by scripts/selfhost/celld-project.ts imports this module. The
 * Cloudflare build's entry is `src/index.ts`, which does not, so the Cloudflare bundle carries
 * neither the class nor the vendored git code (tests/unit/selfhost/selfhost-only-modules.test.ts
 * fails if the shared entry reaches them again). The celld config declares the `HOSTED_GIT`
 * binding and the class's migration (`SELFHOST_DURABLE_OBJECTS` in
 * scripts/selfhost/selfhost-durable-objects.ts); `apps/api/wrangler.toml` does not.
 *
 * The rest of hosted git is shared code: `services/hosted-git/` selects Cloudflare Artifacts or
 * this git server (`resolveArtifactsBackend`) and reaches the Durable Object only through the
 * `HOSTED_GIT` namespace binding, which exists only on a self-host deployment.
 */
import type { Hono } from 'hono';

import type { Env } from '../env';
import { isLocalHostedGitActive } from '../services/hosted-git/backend';
import { handleHostedGitRequest, HOSTED_GIT_PATH_PREFIX } from '../services/hosted-git/http';

export { HostedGitRepo } from '../durable-objects/hosted-git-repo';

/**
 * Mounts git smart HTTP for SAM-hosted repositories (`/git/<repo>.git/...`). Authenticated per
 * request with a repository token, not a session cookie. Inactive (falls through to the 404
 * handler) unless this install uses the local hosted git backend.
 *
 * Call it once, after `src/index.ts` has registered the shared routes. Hono runs every matching
 * handler in registration order, and nothing `index.ts` registers after its global middleware
 * matches `/git/*`, so the route runs after exactly the middleware every request gets (preview,
 * pages proxy, workspace proxy, request logging, analytics, CORS), inside the request-scoped D1
 * session of the default `fetch`. tests/unit/selfhost/hosted-git-route-order.test.ts pins that.
 */
export function mountHostedGitRoute(app: Hono<{ Bindings: Env }>): void {
  // An empty app means this is not the instance index.ts registered on (for example a bundle that
  // loaded app.ts twice); the route would then serve nothing and every clone would 404 silently.
  if (app.routes.length === 0) {
    throw new Error('mountHostedGitRoute: the app has no routes; mount after src/index.ts');
  }
  app.all(`${HOSTED_GIT_PATH_PREFIX}*`, async (c, next) => {
    if (!isLocalHostedGitActive(c.env)) return next();
    const response = await handleHostedGitRequest(c.req.raw, c.env);
    return response ?? next();
  });
}
